112	    func subscribeForUpdates() async {
113	        guard !subscribedForUpdates else {
114	            MXLog.warning("Room already subscribed for updates")
115	            return
116	        }
117	        
118	        subscribedForUpdates = true
119	
120	        do {
121	            try await roomListService.subscribeToRooms(roomIds: [id])
122	        } catch {
123	            MXLog.error("Failed subscribing to room with error: \(error)")
124	        }
125	        
126	        await timeline.subscribeForUpdates()
127	        
128	        Task {
129	            subscribeToRoomInfoUpdates()
130	            
131	            subscribeToTypingNotifications()
132	            
133	            await subscribeToKnockRequests()
134	            
135	            if infoPublisher.value.isEncrypted {
136	                await subscribeToIdentityStatusChanges()
137	            }
138	        }
139	    }
