152	    func timelineFocusedOnEvent(eventID: String, numberOfEvents: UInt16) async -> Result<TimelineProxyProtocol, RoomProxyError> {
153	        do {
154	            let openRoomSpan = analyticsService.signpost.addSpan(.timelineLoad, toTransaction: .notificationToMessage)
155	            let sdkTimeline = try await room.timelineWithConfiguration(configuration: .init(focus: .event(eventId: eventID,
156	                                                                                                          numContextEvents: numberOfEvents,
157	                                                                                                          threadMode: .automatic(hideThreadedEvents: appSettings.threadsEnabled)),
158	                                                                                            filter: .all,
159	                                                                                            internalIdPrefix: UUID().uuidString,
160	                                                                                            dateDividerMode: .daily,
161	                                                                                            trackReadReceipts: .disabled,
162	                                                                                            reportUtds: true))
163	            openRoomSpan?.finish()
164	            
165	            return .success(TimelineProxy(timeline: sdkTimeline, kind: .detached))
166	        } catch let error as FocusEventError {
167	            switch error {
168	            case .InvalidEventId(_, let error):
169	                MXLog.error("Invalid event \(eventID) Error: \(error)")
170	                return .failure(.eventNotFound)
171	            case .EventNotFound:
172	                MXLog.error("Event \(eventID) not found.")
173	                return .failure(.eventNotFound)
174	            case .Other(let message):
175	                MXLog.error("Failed to create a timeline focussed on event \(eventID) Error: \(message)")
176	                return .failure(.sdkError(error))
177	            }
178	        } catch {
179	            MXLog.error("Unexpected error: \(error)")
180	            return .failure(.sdkError(error))
181	        }
182	    }
