213	    func messageFilteredTimeline(focus: TimelineFocus,
214	                                 allowedMessageTypes: [TimelineAllowedMessageType],
215	                                 presentation: TimelineKind.MediaPresentation) async -> Result<any TimelineProxyProtocol, RoomProxyError> {
216	        do {
217	            let rustFocus: MatrixRustSDK.TimelineFocus = switch focus {
218	            case .live: .live(hideThreadedEvents: false)
219	            case .eventID(let eventID): .event(eventId: eventID, numContextEvents: 100, threadMode: .automatic(hideThreadedEvents: false))
220	            case .thread(let eventID): .thread(rootEventId: eventID)
221	            case .pinned: .pinnedEvents
222	            }
223	            
224	            let rustMessageTypes: [MatrixRustSDK.RoomMessageEventMessageType] = allowedMessageTypes.map {
225	                switch $0 {
226	                case .audio: .audio
227	                case .file: .file
228	                case .image: .image
229	                case .video: .video
230	                }
231	            }
232	            
233	            let sdkTimeline = try await room.timelineWithConfiguration(configuration: .init(focus: rustFocus,
234	                                                                                            filter: .onlyMessage(types: rustMessageTypes),
235	                                                                                            internalIdPrefix: nil,
236	                                                                                            dateDividerMode: .monthly,
237	                                                                                            trackReadReceipts: .disabled,
238	                                                                                            reportUtds: true))
239	            
240	            let timeline = TimelineProxy(timeline: sdkTimeline, kind: .media(presentation))
241	            await timeline.subscribeForUpdates()
242	            
243	            return .success(timeline)
244	        } catch {
245	            MXLog.error("Failed retrieving media events timeline with error: \(error)")
246	            return .failure(.sdkError(error))
247	        }
248	    }
