250	    func pinnedEventsTimeline() async -> Result<TimelineProxyProtocol, RoomProxyError> {
251	        // Check if is already available.
252	        if let innerPinnedEventsTimeline {
253	            return .success(innerPinnedEventsTimeline)
254	            // Otherwise check if there is already a task loading it, and wait for it.
255	        } else if let innerPinnedEventsTimelineTask {
256	            return await innerPinnedEventsTimelineTask.value
257	        } else { // Else create and store a new task to load it and wait for it.
258	            let task = Task<Result<TimelineProxyProtocol, RoomProxyError>, Never> { [weak self] in
259	                guard let self else {
260	                    return .failure(.failedCreatingPinnedTimeline)
261	                }
262	                
263	                do {
264	                    let sdkTimeline = try await room.timelineWithConfiguration(configuration: .init(focus: .pinnedEvents,
265	                                                                                                    filter: .all,
266	                                                                                                    internalIdPrefix: nil,
267	                                                                                                    dateDividerMode: .daily,
268	                                                                                                    trackReadReceipts: .disabled,
269	                                                                                                    reportUtds: true))
270	                    
271	                    let timeline = TimelineProxy(timeline: sdkTimeline, kind: .pinned)
272	                    
273	                    await timeline.subscribeForUpdates()
274	                    innerPinnedEventsTimeline = timeline
275	                    return .success(timeline)
276	                } catch {
277	                    MXLog.error("Failed creating pinned events timeline with error: \(error)")
278	                    return .failure(.sdkError(error))
279	                }
280	            }
281	            
282	            innerPinnedEventsTimelineTask = task
283	            return await task.value
284	        }
285	    }
