305	    private func buildPinnedEventContents(timelineItems: [TimelineItemProxy]) {
306	        var pinnedEventContents = OrderedDictionary<String, AttributedString>()
307	        
308	        for item in timelineItems {
309	            // Only remote events are pinned
310	            if case let .event(event) = item,
311	               let eventID = event.id.eventID {
312	                pinnedEventContents.updateValue(pinnedEventStringBuilder.buildAttributedString(for: event) ?? AttributedString(L10n.commonUnsupportedEvent),
313	                                                forKey: eventID)
314	            }
315	        }
316	        
317	        state.pinnedEventsBannerState.setPinnedEventContents(pinnedEventContents)
318	        
319	        // If it's the first time we are setting the pinned events, we should select the initial event if available.
320	        if let initialSelectedPinnedEventID {
321	            state.pinnedEventsBannerState.setSelectedPinnedEventID(initialSelectedPinnedEventID)
322	            self.initialSelectedPinnedEventID = nil
323	        }
324	    }
